{
  "name": "reconcile_supplier_invoices_orders_bank",
  "kind": "workflow",
  "description": "Parses supplier invoices and reconciles them against purchase orders and bank statement, reporting evidenced findings.",
  "signature": {
    "in": "{\"type\":\"object\",\"properties\":{\"folder\":{\"type\":\"string\"},\"checks\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"enum\":[\"duplicate\",\"price_mismatch\",\"quantity_mismatch\",\"no_order\",\"double_payment\"]}},\"supplier_filter\":{\"type\":\"string\"}},\"required\":[\"folder\"]}",
    "out": "output of s2"
  },
  "steps": [
    {
      "id": "s1",
      "uses": "parse_supplier_invoices",
      "foreach": null,
      "inputs": [
        {
          "param": "folder",
          "source": "$input.folder"
        }
      ]
    },
    {
      "id": "s2",
      "uses": "reconcile_invoices_orders_bank",
      "foreach": null,
      "inputs": [
        {
          "param": "folder",
          "source": "$input.folder"
        },
        {
          "param": "invoices",
          "source": "$steps.s1.invoices"
        },
        {
          "param": "checks",
          "source": "$input.checks"
        },
        {
          "param": "supplier_filter",
          "source": "$input.supplier_filter"
        }
      ]
    }
  ],
  "output_step": "s2",
  "permissions": {
    "net": [],
    "llm": false
  },
  "budget": {
    "max_tokens_per_run": 0
  },
  "lineage": {
    "created_by": "factory",
    "uses": [
      "parse_supplier_invoices@v1",
      "reconcile_invoices_orders_bank@v2"
    ]
  },
  "example_input": "{\"folder\":\"novak_trading\",\"checks\":[\"duplicate\",\"price_mismatch\",\"quantity_mismatch\",\"no_order\",\"double_payment\"],\"supplier_filter\":\"\"}",
  "purpose": "a bot that reconciles our supplier invoices against the purchase orders and the bank statement: find duplicate invoices, price or quantity mismatches, invoices without an order and double payments, with the evidence (file, invoice number, amounts) for every finding\n\nFiles: folder novak_trading",
  "version": 2,
  "headline": "Checked {summary.invoices_checked} invoices and found {summary.findings} issues; the first is a {findings.0.type} on invoice {findings.0.invoice_number} ({findings.0.detail}), a difference of {findings.0.difference_czk} CZK.",
  "examples": [
    "Are there any duplicate invoices or double payments?",
    "Which invoices have no purchase order?",
    "Check only price mismatches for OfficeLine"
  ],
  "manual_minutes": 240.0,
  "manual_basis": "Open each supplier invoice PDF and key invoice number, date, lines, quantities and amounts into a spreadsheet, then match them against purchase orders and bank statement lines to flag duplicates, pric",
  "build_usd": 0.2569,
  "build_seconds": 149,
  "voice": "ghoul"
}

